import{_ as t,o,c as a,a2 as i}from"./chunks/framework.BN2sqjC1.js";const h=JSON.parse('{"title":"ADR-0044 — Watcher su macOS con FSEvents (via purego) al posto di kqueue","description":"","frontmatter":{},"headers":[],"relativePath":"adr/0044-watcher-fsevents-macos.md","filePath":"adr/0044-watcher-fsevents-macos.md"}'),r={name:"adr/0044-watcher-fsevents-macos.md"};function c(n,e,s,d,l,u){return o(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="adr-0044-—-watcher-su-macos-con-fsevents-via-purego-al-posto-di-kqueue" tabindex="-1">ADR-0044 — Watcher su macOS con FSEvents (via purego) al posto di kqueue <a class="header-anchor" href="#adr-0044-—-watcher-su-macos-con-fsevents-via-purego-al-posto-di-kqueue" aria-label="Permalink to &quot;ADR-0044 — Watcher su macOS con FSEvents (via purego) al posto di kqueue&quot;">​</a></h1><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><strong>Stato</strong></td><td>accettata</td></tr><tr><td><strong>Recepito in</strong></td><td><code>Specifications.md</code> v1.2 (2026-11-02): §1.4, §2.4, §2.5, §3.4.4 A, §4.2, C.2 (Appendice C.4)</td></tr><tr><td><strong>Data</strong></td><td>2026-11-01</td></tr><tr><td><strong>Riferimenti spec</strong></td><td>§2.5 &quot;watcher&quot; (tabella dei moduli), §3.8 A &quot;Rilevamento locale&quot;, registro dei rischi (affidabilità <code>fsnotify</code>)</td></tr><tr><td><strong>Devia dallo spec?</strong></td><td>sì (§2.5 e §3.8 A citano solo <code>fsnotify</code>) → richiede aggiornamento di <code>Specifications.md</code> da parte dell&#39;owner</td></tr></tbody></table><h2 id="contesto" tabindex="-1">Contesto <a class="header-anchor" href="#contesto" aria-label="Permalink to &quot;Contesto&quot;">​</a></h2><p>Su macOS <code>fsnotify</code> usa kqueue, che tiene aperto <strong>un descrittore per ogni file</strong> di ogni cartella osservata (oltre a uno per cartella). Misura sui dataset di <code>task perf</code> (<code>TestWatcherDescriptors</code>, <code>MEMOBRAIN_WATCH_FD_DIR</code>):</p><table tabindex="0"><thead><tr><th>vault</th><th>fsnotify (kqueue)</th><th>FSEvents</th></tr></thead><tbody><tr><td>10 052 file in 328 cartelle</td><td>10 378 fd, avvio 0,5 s</td><td>11 fd, avvio 5 ms</td></tr><tr><td>50 252 file in 718 cartelle</td><td>50 973 fd, avvio 3,1 s</td><td>11 fd, avvio 5 ms</td></tr></tbody></table><p>Con <code>kern.maxfilesperproc</code> (122 880 sulla macchina di misura, meno su altre configurazioni) un vault Obsidian con molti allegati porta il processo a <code>EMFILE</code>: falliscono allora tutte le aperture (index.db, sync.db, scritture atomiche, socket). Il rilievo era stato rinviato in M11-W4.</p><h2 id="decisione" tabindex="-1">Decisione <a class="header-anchor" href="#decisione" aria-label="Permalink to &quot;Decisione&quot;">​</a></h2><ul><li>Su macOS il watcher usa <strong>FSEvents</strong>: un solo stream ricorsivo sulla radice del vault (<code>kFSEventStreamCreateFlagFileEvents | NoDefer | WatchRoot</code>, latenza 50 ms, coda dispatch seriale), nessun descrittore per file. Le API di CoreServices/CoreFoundation/libdispatch sono raggiunte con <code>github.com/ebitengine/purego</code> (già nel grafo delle dipendenze, ora diretta): niente cgo, la build incrociata resta possibile.</li><li>Gli eventi passano dallo stesso debounce/coalescing; i flag <code>MustScanSubDirs</code>, <code>UserDropped</code>, <code>KernelDropped</code>, <code>RootChanged</code> producono una riconciliazione completa. I path reali (<code>/private/var/…</code>) sono ricondotti alla radice del vault; <code>.git/</code> e i file interni restano esclusi.</li><li>Se FSEvents non si inizializza si torna a <code>fsnotify</code>.</li><li>Su Linux/Windows resta <code>fsnotify</code> (inotify: un watch per cartella). Al raggiungimento di un limite di sistema (<code>ENOSPC</code> di <code>max_user_watches</code>, <code>EMFILE</code>/<code>ENFILE</code>) il watcher smette di aggiungere watch, conta le cartelle non osservate (<code>Watcher.Degraded()</code>), lo registra una volta e porta la riconciliazione a 1 minuto.</li><li>Nel browser la riconciliazione periodica è disattivata per default: lì solo il core scrive e notifica ogni scrittura (<code>Watcher.Notify</code>).</li></ul><h2 id="alternative-considerate" tabindex="-1">Alternative considerate <a class="header-anchor" href="#alternative-considerate" aria-label="Permalink to &quot;Alternative considerate&quot;">​</a></h2><ul><li><strong><code>github.com/fsnotify/fsevents</code></strong> — richiede cgo e non è tra le dipendenze; purego dà lo stesso risultato senza toolchain C.</li><li><strong>kqueue solo sulle cartelle + riscansione</strong> — un descrittore per cartella, ma le scritture in place (VS Code, <code>&gt;&gt;</code>) non modificano la cartella e sarebbero viste solo dalla riconciliazione.</li><li><strong>Tetto ai watch + riconciliazione più frequente</strong> — limita i danni ma su vault grandi lascia quasi tutto alla riconciliazione.</li></ul><h2 id="conseguenze" tabindex="-1">Conseguenze <a class="header-anchor" href="#conseguenze" aria-label="Permalink to &quot;Conseguenze&quot;">​</a></h2><ul><li>Il watcher di macOS non consuma più descrittori in proporzione al vault; l&#39;avvio dell&#39;osservazione è immediato.</li><li>purego diventa dipendenza diretta del desktop (callback C verso Go: una sola callback condivisa, i callback purego non si liberano).</li><li>Il percorso <code>fsnotify</code> su macOS resta solo come ripiego: i test di watcher su macOS esercitano FSEvents, quelli su Linux <code>fsnotify</code>.</li><li>Da recepire nello spec: §2.5 (tabella <code>watcher</code>) e §3.8 A (&quot;FSEvents su macOS, <code>fsnotify</code> altrove&quot;).</li></ul>',12)])])}const g=t(r,[["render",c]]);export{h as __pageData,g as default};
